// Category transactions exercise production state, parser, history and disk export.
#include "pxwe_project.h"
#include "cartridge_damage.h"
#include <chrono>
#include <cmath>
#include <fstream>
#include <functional>
#include <iostream>
#include <set>
using namespace pxwe;
namespace {
int passed=0,failed=0;
void Check(bool value,const char* why){if(!value)throw std::runtime_error(why);}
void Reject(const std::function<void()>& f){bool rejected=false;try{f();}catch(const std::exception&){rejected=true;}Check(rejected,"expected rejection");}
struct Temp {fs::path path=fs::temp_directory_path()/("pxwe-categories-"+std::to_string(std::chrono::steady_clock::now().time_since_epoch().count()));Temp(){fs::create_directory(path);}~Temp(){std::error_code ec;fs::remove_all(path,ec);}};
void Test(const char* name,const std::function<void(const fs::path&)>& fn){try{Temp t;fn(t.path);++passed;std::cout<<"PASS "<<name<<'\n';}catch(const std::exception& e){++failed;std::cerr<<"FAIL "<<name<<": "<<e.what()<<'\n';}}
void Put(const fs::path& path,const std::string& text){fs::create_directories(path.parent_path());std::ofstream out(path,std::ios::binary);out<<text;}
std::string Read(const fs::path& path){std::ifstream in(path,std::ios::binary);return {std::istreambuf_iterator<char>(in),std::istreambuf_iterator<char>()};}
Project Basic(const fs::path& root){Project p;p.Load(root);p.Add(Kind::Cartridge,"fmj");p.Add(Kind::Cartridge,"jhp","fmj");p.Add(Kind::Weapon,"pistol");p.Allow("pistol","jhp","300");p.Save();return p;}
std::string StateText(const Project& p){std::string s;for(const auto& a:p.Data().cartridges)s+=a.Serialize();for(const auto& a:p.Data().weapons)s+=a.Serialize();std::set<std::string> folders;for(const auto& c:p.Data().categories)folders.insert((c.kind==Kind::Weapon?"W:":"C:")+c.path);for(const auto& c:folders)s+=c+'\n';return s;}
}
int main(){
    Test("category grammar matches bounded format-3 paths",[](const auto&){Check(ValidCategory("rifles/sg550/camo")&&ValidCategory("9x19/FMJ")&&ValidCategory("",true)&&!ValidCategory(""),"basic grammar");for(const auto& s:{"/a","a/","a//b","a/../b","a b","a\\b","a\nb"})Check(!ValidCategory(s),"bad path accepted");std::string path="a";for(int i=1;i<16;++i)path+="/a";Check(ValidCategory(path)&&!ValidCategory(path+"/a"),"depth limit");path=std::string(63,'a')+"/"+std::string(63,'b')+"/"+std::string(63,'c')+"/"+std::string(63,'d');Check(path.size()==255&&ValidCategory(path)&&!ValidCategory(path+"e"),"length limit");Check(CategoryParent("a/b/c")=="a/b"&&CategoryParent("a").empty(),"parents");});
    Test("empty folders persist and do not alter gameplay fingerprints",[](const auto& root){auto p=Basic(root);const auto fingerprint=p.Validate().registry.Fingerprint();p.CreateCategory(Kind::Weapon,"rifles/camo/empty");p.CreateCategory(Kind::Cartridge,"9x19/fmj");Check(p.Categories(Kind::Weapon)==std::vector<std::string>({"rifles","rifles/camo","rifles/camo/empty"}),"parents missing");Check(p.Validate().registry.Fingerprint()==fingerprint&&p.Dirty(),"editor folders changed registry");p.Save();Project q;q.Load(root);Check(!q.Dirty()&&q.Data().categories.size()==2&&q.Categories(Kind::Weapon)==p.Categories(Kind::Weapon),"empty folders lost");Check(q.Validate().registry.Fingerprint()==fingerprint,"sidecar consumed by game");});
    Test("category creation undo redo cancellation-equivalent and limits",[](const auto& root){auto p=Basic(root);p.CreateCategory(Kind::Weapon,"a/b");const auto before=StateText(p);Reject([&]{p.CreateCategory(Kind::Weapon,"a");});Reject([&]{p.CreateCategory(Kind::Weapon,"a//bad");});Check(StateText(p)==before,"bad create mutated");Check(p.Undo()&&p.Categories(Kind::Weapon).empty()&&!p.Dirty(),"create not atomic");p.Redo();Check(p.Categories(Kind::Weapon).size()==2,"redo lost folders");for(int i=1;i<256;++i)p.CreateCategory(Kind::Cartridge,"folder_"+std::to_string(i));Reject([&]{p.CreateCategory(Kind::Weapon,"overflow");});Check(p.Data().categories.size()==256,"folder limit bypassed");});
    Test("legacy cartridge assignment converts damage in one undo step",[](const auto& root){auto p=Basic(root);const auto before=p.Find(Kind::Cartridge,"fmj")->Serialize();const auto damage=p.Validate().registry.FindCartridge("fmj")->damage;p.SetCategory(Kind::Cartridge,"fmj","9x19/fmj");const auto v=p.Validate();const auto* c=v.registry.FindCartridge("fmj");Check(v.Ok()&&c->schemaVersion==3&&c->category=="9x19/fmj"&&p.Find(Kind::Cartridge,"fmj")->Get("damage").empty(),"conversion incomplete");Check(std::abs(modular::MuzzleDamage(*c,c->referenceVelocityMps)-damage)<.0001,"damage changed");Check(p.Undo()&&p.Find(Kind::Cartridge,"fmj")->Serialize()==before,"assignment split history");p.Redo();p.SetCategory(Kind::Cartridge,"fmj","");Check(p.Validate().Ok()&&p.Find(Kind::Cartridge,"fmj")->Get("version")=="3","clear downgraded");});
    Test("format-one cartridge category retains implicit historical damage",[](const auto& root){auto p=Basic(root);p.SetField(Kind::Cartridge,"fmj","version","1");p.SetField(Kind::Cartridge,"fmj","damage","");const auto v=p.Validate();Check(v.Ok(),"version one fixture");const auto damage=v.registry.FindCartridge("fmj")->damage;p.SetCategory(Kind::Cartridge,"fmj","legacy/fmj");const auto c=*p.Validate().registry.FindCartridge("fmj");Check(std::abs(modular::MuzzleDamage(c,c.referenceVelocityMps)-damage)<.0001,"implicit damage lost");});
    Test("failed conversion leaves all assets and history intact",[](const auto& root){auto p=Basic(root);p.Allow("pistol","fmj","10000");const auto before=StateText(p);Reject([&]{p.SetCategory(Kind::Cartridge,"fmj","hot/fmj");});Check(StateText(p)==before,"partial upgrade");Check(p.Undo()&&p.Find(Kind::Weapon,"pistol")->accepted.front().second=="360","rejection added history");});
    Test("weapon property category moves use atomic conversion and keep IDs paths",[](const auto& root){auto p=Basic(root);const auto old=p.Find(Kind::Weapon,"pistol")->Serialize();p.SetField(Kind::Weapon,"pistol","category"," pistols/service ");const auto* w=p.Find(Kind::Weapon,"pistol");Check(w->Get("version")=="3"&&w->Get("category")=="pistols/service"&&w->Id()=="pistol"&&w->Get("view_model")=="models/v_pistol.mdl","move changed identity");p.Undo();Check(p.Find(Kind::Weapon,"pistol")->Serialize()==old,"property move split history");Reject([&]{p.SetCategory(Kind::Weapon,"pistol","../bad");});Check(!p.Dirty(),"invalid category changed data");});
    Test("new and duplicated assets inherit explicit destination atomically",[](const auto& root){auto p=Basic(root);p.CreateCategory(Kind::Cartridge,"new/empty");p.Add(Kind::Cartridge,"new_round","","new/empty");Check(p.Validate().Ok()&&p.Find(Kind::Cartridge,"new_round")->Get("version")=="3","new round did not convert");p.Undo();Check(!p.Find(Kind::Cartridge,"new_round"),"new category asset split history");p.SetCategory(Kind::Weapon,"pistol","pistols");p.Add(Kind::Weapon,"copy","pistol","");Check(p.Find(Kind::Weapon,"copy")->Get("category").empty()&&p.Find(Kind::Weapon,"copy")->Get("view_model")=="models/v_pistol.mdl","root copy not explicit");p.Undo();Check(!p.Find(Kind::Weapon,"copy"),"duplicate split history");});
    Test("subtree relocation preserves relative nesting and prefix boundaries",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","arms/pistols/service");p.Add(Kind::Weapon,"other","pistol","arms2/pistols");p.CreateCategory(Kind::Weapon,"arms/pistols/empty");p.CreateCategory(Kind::Cartridge,"arms/pistols");const auto before=StateText(p);p.RelocateCategory(Kind::Weapon,"arms","equipment");Check(p.Find(Kind::Weapon,"pistol")->Get("category")=="equipment/pistols/service"&&p.Find(Kind::Weapon,"other")->Get("category")=="arms2/pistols","wrong prefix rewrite");Check(p.Categories(Kind::Cartridge)==std::vector<std::string>({"arms","arms/pistols"}),"other kind moved");Check(p.Undo()&&StateText(p)==before,"subtree move split history");p.Redo();p.Save();Project q;q.Load(root);Check(StateText(q)==StateText(p)&&!q.Dirty(),"subtree round trip mismatch");});
    Test("relocation cycles collisions unknown roots and deep destinations reject atomically",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","a/b");p.CreateCategory(Kind::Weapon,"other");const auto before=StateText(p);for(const auto& target:{"a/b/c","other","","../bad"})Reject([&]{p.RelocateCategory(Kind::Weapon,"a",target);});std::string deep="z";for(int i=1;i<16;++i)deep+="/z";Reject([&]{p.RelocateCategory(Kind::Weapon,"a",deep);});Reject([&]{p.RelocateCategory(Kind::Weapon,"missing","new");});p.RelocateCategory(Kind::Weapon,"a","a");Check(StateText(p)==before,"rejection/noop moved assets");Check(p.Undo()&&p.Categories(Kind::Weapon)==std::vector<std::string>({"a","a/b"}),"rejected move added history");});
    Test("subtree duplication preserves resources references and allocates runtime IDs",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","pistols/service");p.PutVariant("pistol","jhp","reload_sound","weapons/jhp.wav","ammo:jhp");p.SetAmmoOverrides("pistol","fmj",{{"view_model","models/v_fmj.mdl"}});p.Add(Kind::Weapon,"backup","pistol","pistols/backup");p.CreateCategory(Kind::Weapon,"pistols/empty");const auto before=StateText(p);p.DuplicateCategory(Kind::Weapon,"pistols","copies","copy");Check(p.Data().weapons.size()==4&&p.Data().cartridges.size()==2,"wrong copies");std::set<std::string> runtime;for(const auto& w:p.Data().weapons)Check(runtime.insert(w.Get("runtime_id")).second,"duplicate runtime IDs");const auto* w=p.Find(Kind::Weapon,"copy_pistol");Check(w->Get("category")=="copies/service"&&w->Get("view_model")=="models/v_pistol.mdl"&&w->Get("default_cartridge")=="fmj"&&w->Get("asset.jhp.when")=="ammo:jhp"&&w->Get("ammo.fmj.view_model")=="models/v_fmj.mdl","copy changed references");Check(p.Undo()&&StateText(p)==before,"copy split history");p.Redo();p.Save();Project q;q.Load(root);Check(q.Validate().Ok()&&StateText(q)==StateText(p),"copies failed save");});
    Test("cartridge category duplication leaves existing weapon references intact",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Cartridge,"fmj","9x19/fmj");p.SetCategory(Kind::Cartridge,"jhp","9x19/jhp");const auto weapon=p.Find(Kind::Weapon,"pistol")->Serialize();p.DuplicateCategory(Kind::Cartridge,"9x19","trial","trial");Check(p.Data().cartridges.size()==4&&p.Find(Kind::Cartridge,"trial_fmj")->Get("category")=="trial/fmj"&&p.Find(Kind::Weapon,"pistol")->Serialize()==weapon,"cartridge copy redirected ammo");});
    Test("copy disk collisions reject after staging without partial state",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","source");p.Add(Kind::Weapon,"backup","pistol","source");Put(root/"scripts/weapons/COPY_backup.weapon","unlisted");const auto before=StateText(p);Reject([&]{p.DuplicateCategory(Kind::Weapon,"source","new","copy");});Check(StateText(p)==before&&!p.Find(Kind::Weapon,"copy_pistol"),"partial copies committed");Check(Read(root/"scripts/weapons/COPY_backup.weapon")=="unlisted","unlisted file overwritten");Check(p.Undo()&&!p.Find(Kind::Weapon,"backup"),"rejection added history");});
    Test("runtime ID exhaustion rolls back an entire subtree copy",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","source");for(int i=1;i<31;++i)p.Add(Kind::Weapon,"w_"+std::to_string(i),"pistol","");const auto before=StateText(p);Reject([&]{p.DuplicateCategory(Kind::Weapon,"source","copy","copy");});Check(StateText(p)==before&&!p.Find(Kind::Weapon,"copy_pistol"),"exhausted copy mutated");});
    Test("removing category keeps all assets at parent and is one undo action",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","arms/pistols/service");p.CreateCategory(Kind::Weapon,"arms/pistols/empty");const auto before=StateText(p);p.RemoveCategory(Kind::Weapon,"arms/pistols");Check(p.Find(Kind::Weapon,"pistol")->Get("category")=="arms"&&p.Categories(Kind::Weapon)==std::vector<std::string>{"arms"},"remove kept subtree");Check(p.Undo()&&StateText(p)==before,"remove not atomic");p.Redo();p.Save();Project q;q.Load(root);Check(q.Categories(Kind::Weapon)==std::vector<std::string>{"arms"}&&!fs::exists(root/"scripts/editor_categories.txt"),"removed folders persisted");});
    Test("referenced cartridge subtree deletion rejects every deletion",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Cartridge,"fmj","ammo");p.Add(Kind::Cartridge,"unused","fmj","ammo/sub");const auto before=StateText(p);Reject([&]{p.RemoveCategory(Kind::Cartridge,"ammo",true);});Check(StateText(p)==before&&p.Find(Kind::Cartridge,"unused"),"partial cartridge deletion");});
    Test("weapon subtree deletion keeps ammunition and unlisted files",[](const auto& root){auto p=Basic(root);p.SetCategory(Kind::Weapon,"pistol","weapons/sub");p.CreateCategory(Kind::Weapon,"weapons/empty");p.Save();Put(root/"scripts/weapons/unlisted.weapon","keep");p.RemoveCategory(Kind::Weapon,"weapons",true);Check(p.Data().weapons.empty()&&p.Data().cartridges.size()==2&&p.Validate().Ok(),"delete affected ammo");p.Save();Check(!fs::exists(root/"scripts/weapons/pistol.weapon")&&Read(root/"scripts/weapons/unlisted.weapon")=="keep","wrong disk deletions");p.Undo();p.Save();Check(fs::exists(root/"scripts/weapons/pistol.weapon"),"delete/save undo failed");});
    Test("external sidecar changes block export before touching definitions",[](const auto& root){auto p=Basic(root);p.CreateCategory(Kind::Weapon,"empty");p.Save();const auto old=Read(root/"scripts/weapons/pistol.weapon");p.SetField(Kind::Weapon,"pistol","clip_size","25");Put(root/"scripts/editor_categories.txt","version = 1\nweapon = external\n");Reject([&]{p.Save();});Check(Read(root/"scripts/weapons/pistol.weapon")==old&&p.Dirty(),"sidecar conflict wrote data");});
    Test("new sidecar collisions and containment are protected",[](const auto& root){auto p=Basic(root);p.CreateCategory(Kind::Weapon,"empty");Put(root/"scripts/editor_categories.txt","version = 1\nweapon = external\n");Reject([&]{p.Save();});Check(Read(root/"scripts/editor_categories.txt").find("external")!=std::string::npos,"new sidecar overwritten");fs::remove(root/"scripts/editor_categories.txt");const auto outside=root.parent_path()/(root.filename().string()+"-outside");fs::create_directory(outside);Put(outside/"categories","version = 1\nweapon = external\n");fs::create_symlink(outside/"categories",root/"scripts/editor_categories.txt");Reject([&]{p.Save();});fs::remove(root/"scripts/editor_categories.txt");fs::remove_all(outside);});
    Test("malformed sidecars reject open without losing current project",[](const auto& root){auto p=Basic(root);const auto before=StateText(p);for(const auto& text:{"version = 2\n","weapon = a\n","version = 1\nweapon = ../bad\n","version = 1\nweapon = a\nweapon = a\n","version = 1\nother = a\n"}){Put(root/"scripts/editor_categories.txt",text);Reject([&]{p.Load(root);});Check(StateText(p)==before&&p.Root()==root,"bad open replaced project");}});
    Test("legacy packs save without creating category metadata or changing fingerprint",[](const auto& root){auto p=Basic(root);const auto before=p.Validate().registry.Fingerprint();p.SetCategory(Kind::Weapon,"pistol","");Check(!p.Dirty()&&p.Find(Kind::Weapon,"pistol")->Get("version")=="2","blank edit upgraded");p.Save();Project q;q.Load(root);Check(!fs::exists(root/"scripts/editor_categories.txt")&&q.Validate().registry.Fingerprint()==before,"legacy pack changed");});
    Test("numeric format-three aliases retain authored coefficient on categorization",[](const auto& root){auto p=Basic(root);p.SetCoefficient("fmj","3");p.SetField(Kind::Cartridge,"fmj","version","03");Check(p.Validate().Ok(),"numeric schema alias fixture");p.SetCategory(Kind::Cartridge,"fmj","9x19/fmj");Check(p.Validate().Ok()&&p.Find(Kind::Cartridge,"fmj")->Get("damage_coefficient")=="3","coefficient replaced by legacy damage");});
    Test("category assignment repairs legacy category drafts during conversion",[](const auto& root){auto p=Basic(root);auto draft=*p.Find(Kind::Cartridge,"fmj");draft.Set("category","bad//draft");Put(root/"scripts/cartridges/fmj.cartridge",draft.Serialize());p.Load(root);Check(!p.Validate().Ok(),"invalid draft fixture");p.SetCategory(Kind::Cartridge,"fmj","9x19/repaired");Check(p.Validate().Ok()&&p.Find(Kind::Cartridge,"fmj")->Get("version")=="3","category draft cannot be repaired");});
    std::cout<<passed<<" passed, "<<failed<<" failed\n";return failed?1:0;
}
